    references: [{ type: "book", title: `The Grand Design`, author: `Stephen Hawking`, note: `Uses Occam's Razor in discussing competing theories of physics.` }, { type: "newsletter", title: `Farnam Street`, author: `Shane Parrish`, note: `One of the best practical guides to applying Occam's Razor.` }],
