    references: [{ type: "article", title: `The Propinquity Effect`, author: `Festinger, Schachter & Back`, note: `The classic 1950 study of how physical proximity determines friendship.` }, { type: "book", title: `The Laws of Human Nature`, author: `Robert Greene`, note: `Includes propinquity in its analysis of social influence.` }],
